int add_mtd_partitions(struct mtd_info *parent,
		       const struct mtd_partition *parts,
		       int nbparts)
{
	struct mtd_info *child, *master = mtd_get_master(parent);
	uint64_t cur_offset = 0;
	int i, ret;

	printk(KERN_NOTICE "Creating %d MTD partitions on \"%s\":\n",
	       nbparts, parent->name);

	for (i = 0; i < nbparts; i++) {
		mutex_lock(&master->master.partitions_lock);
		if (master->master.unregistering ||
		    (mtd_is_partition(parent) && !parent->registered)) {
			mutex_unlock(&master->master.partitions_lock);
			return -ENODEV;
		}

		child = allocate_partition(parent, parts + i, i, cur_offset);
		if (IS_ERR(child)) {
			ret = PTR_ERR(child);
			goto err_unlock;
		}

		if (IS_REACHABLE(CONFIG_MTD_VIRT_CONCAT)) {
			ret = mtd_virt_concat_add(child);
			if (ret < 0) {
				free_partition(child);
				goto err_unlock;
			}
			if (ret) {
				cur_offset = child->part.offset + child->part.size;
				mutex_unlock(&master->master.partitions_lock);
				continue;
			}
		}

		list_add_tail(&child->part.node, &parent->partitions);

		ret = add_mtd_device(child);
		if (ret) {
			list_del(&child->part.node);
			free_partition(child);
			goto err_unlock;
		}

		mtd_add_partition_attrs(child);
		cur_offset = child->part.offset + child->part.size;

		/* Parsing drops the partition lock and may race with deletion. */
		ret = PTR_ERR_OR_ZERO(get_mtd_device(child, -1));
		if (ret)
			goto err_unlock;
		mutex_unlock(&master->master.partitions_lock);

		/* Look for subpartitions (skip if no maching parser found) */
		ret = parse_mtd_partitions(child, parts[i].types, NULL);
		mutex_lock(&master->master.partitions_lock);
		/* Removal of this child must not roll back its siblings. */
		if (!child->registered)
			ret = 0;
		mutex_unlock(&master->master.partitions_lock);
		put_mtd_device(child);
		if (ret < 0 && ret == -ENOENT) {
			pr_debug("Skip parsing subpartitions: %d\n", ret);
			continue;
		} else if (ret < 0) {
			pr_err("Failed to parse subpartitions: %d\n", ret);
			goto err_del_partitions;
		}
	}

	return 0;

err_unlock:
	mutex_unlock(&master->master.partitions_lock);
err_del_partitions:
	del_mtd_partitions(parent);

	return ret;
}

